mapper.select:
select stl.ACCT_NO as accountId, stl.ACCT_NAME as accountName, B.ACCT_TYPE as accountType from STL_CAPACCT_INFO stl LEFT JOIN BOK_BOOKSET_CAPACCT_INFO B on stl.ACCT_NO=B.ACCT_NO where 1=1
and stl.ACCT_NO=#{accountId}
and stl.ACCT_NAME=#{accountName}

select to_char(info.EFF_DATE,'yyyy-mm-dd') as effDate, info.INT_TYPE as intType,
info.RATE*100 as rate, info.BASIS as basis, info.FINPROD_ID as accountId, bok.ACCT_TYPE as accountType, info.CASH_ID as cashId, info.INT_TYPE as intRateStructure, info.BENCHMARK_ID as basicRate
from FIN_RATE_INFO info left join BOK_BOOKSET_CAPACCT_INFO bok on info.FINPROD_ID =bok.ACCT_NO where 1=1
and info.CASH_ID=#{cashId}
and info.EFF_DATE =to_date(#{effDate},'yyyy-mm-dd')
and bok.BOOKSET_ID = #{booksetId}
and bok.CCY = #{ccy}

	select count(1)
	from STL_CAPACCT_INFO stl
LEFT JOIN BOK_BOOKSET_CAPACCT_INFO B
on stl.ACCT_NO=B.ACCT_NO 
where stl.ACCT_NO = #{accNo}
and ACCT_TYPE=#{accType}

select count(1)
from FIN_CASH_INFO
where CASH_ID=#{cashId}
